head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 1; // 현재 선택된 페이지번호

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        scwin.initPage();
        await scwin.listDsclBbs();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30402.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name cmb_PerPage_onselchange
 * @description cmb_PerPage onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_onselchange = function() {
    try {
        scwin.vCurrPageNo = 1;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.cmb_PerPage_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listDsclBbs();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30402.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        const vTotalCnt = dts_Grid.getCellData(1, "CNT");
        // alert("vTotalCnt=" + vTotalCnt);
        $c.stf.FillGridHeader2(scwin.pageNoCnt, cmb_PerPage.getValue(), vTotalCnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30402.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.readDsclBbs(row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30402.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        await scwin.new();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30402.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listDsclBbs
 * @description list Dscl Bbs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listDsclBbs = async function() {
    url += "&MKT_ID=" + rdo_mkt_gubun.getValue();
    url += "&KEYWORD_FLAG=" + cmb_KEYWORD.getValue();
    url += "&KEYWORD=" + txb_KEYWORD.getValue();
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&EMP_NM=" + txb_EMP_NM.getValue();
    url += "&MENU_FLAG=" + cmb_MENU_FLAG.getValue();
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + cmb_PerPage.getValue();
    url += "&PDS=Y"; // 자료실 포함여부.(관리자일때만 자료실을 표시함.)
    url += "&SCREN_ID=" + "ULDSTF30402.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/IntegratedBBS.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description code default value setting
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    // code default value setting
    // 1. 날짜 기본 6개월.
    const ToDay = $c.ut.cGetToday2();
    edt_EDATE.setValue(ToDay);
    const vSDATE = $c.ut.calcMonth(ToDay, -6);
    edt_SDATE.setValue(vSDATE);
    rdo_mkt_gubun.setValue(js_market);
    if (js_bond_yn === 'Y') {
        rdo_mkt_gubun.setValue('4');
    }
    if (js_market === "9") {
        panel_mkt_gubun.show("");
    } else {
        panel_mkt_gubun.hide();
    }
};

/**
 * @method
 * @name PageNoCall
 * @description Page No Call 처리
 * @param {*} vPageNo vPageNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.PageNoCall = async function(vPageNo) {
    scwin.vCurrPageNo = vPageNo;
    await scwin.listDsclBbs();
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    $c.stf.comboCbDataSet(cmb_PerPage);
};

/**
 * @method
 * @name readDsclBbs
 * @description read Dscl Bbs 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDsclBbs = async function(row, colid) {
    if (colid === "TITLE") {
        const CONTN_ID = dts_Grid.getCellData(row, "CONTN_ID");
        const options = {
            id: "ULDSTF30403",
            title: "제도해설등 조회",
            type: "browserPopup",
            width: "750px",
            height: 570 + 30,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclinfo/ULDSTF30403.gfm", options);
    }
};

/**
 * @method
 * @name new
 * @description new 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new = async function() {
    const options = {
        id: "ULDSTF30403",
        title: "제도해설등 신규",
        type: "browserPopup",
        width: "750px",
        height: 570 + 30,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclinfo/ULDSTF30403.gfm", options);
};
